const ev = $json.eventos || [];
const s = $getWorkflowStaticData('global');
if (ev.length) s.cursor = ev[ev.length - 1].ts;
const pick = (t) => ev.filter(e => e.evento === t);
return [{ json: {
  nuevos_calificados: pick('lead.registrado').map(e => `${e.entidad} ${e.detalle.nombre} (${e.detalle.clasificacion})`),
  borradores_listos: pick('borrador.listo').map(e => e.entidad),
  aprobaciones: pick('aprobacion.humana').map(e => `${e.entidad} por ${e.detalle.aprobado_por}`),
  respuestas: pick('respuesta.recibida').map(e => e.entidad),
  bajas: pick('baja.registrada').map(e => e.entidad),
  cambios_estado: pick('lead.estado_cambiado').map(e => `${e.entidad}: ${e.detalle.de} → ${e.detalle.a}`),
  total_eventos: ev.length
} }];
